SELECT p.area_id, COUNT(*) AS customerCount, SUM(c.deal_status) AS dealCount
FROM crm_customer c
INNER JOIN partner p ON c.id = p.id
WHERE c.deleted = 0 AND p.area_id IS NOT NULL
AND c.owner_user_id IN

    #{userId}

AND c.create_time BETWEEN #{times[0],javaType=java.time.LocalDateTime}
AND #{times[1],javaType=java.time.LocalDateTime}
GROUP BY p.area_id

